import type { Metadata } from 'next';
import Link from 'next/link';
import { notFound } from 'next/navigation';
import { services, digitalChildServices } from '@/lib/services';

export function generateStaticParams(){ return services.map(s=>({slug:s.slug})); }
export async function generateMetadata({params}:{params:Promise<{slug:string}>}):Promise<Metadata>{const {slug}=await params;const s=services.find(x=>x.slug===slug);if(!s)return {};return {title:s.metaTitle.replace(' | KeyOn Media',''),description:s.metaDescription,alternates:{canonical:`/services/${s.slug}`},openGraph:{title:s.metaTitle,description:s.metaDescription,type:'website'}}}
export default async function ServicePage({params}:{params:Promise<{slug:string}>}){const {slug}=await params;const s=services.find(x=>x.slug===slug);if(!s)notFound();const related=services.filter(x=>s.related.includes(x.slug));return <>
  <section className={`service-hero detail-${s.visual}`}><div className="container detail-hero-grid"><div><div className="breadcrumb"><Link href="/">Home</Link><span>/</span><Link href="/services/digital-marketing">Services</Link><span>/</span><span>{s.name}</span></div><div className="eyebrow"><span className="eyebrow-line"/>{s.eyebrow}</div><h1>{s.title}</h1><p className="detail-lede">{s.description}</p><div className="hero-actions"><Link href="/contact" className="button">Discuss your brief <span>↗</span></Link><Link href="/portfolio" className="text-link">View our work <span>↗</span></Link></div></div><div className="detail-art"><div className="detail-art-ring ring-a"/><div className="detail-art-ring ring-b"/><div className="detail-art-shape"/><div className="detail-art-label"><span>KEYON MEDIA</span><strong>{s.name.split(' ').map(w=>w[0]).join('').slice(0,4)}</strong><small>IDEAS INTO ACTION</small></div><span className="detail-art-index">SERVICE / {s.eyebrow.slice(0,2).toUpperCase()}</span></div></div></section>
  <section className="section-pad offerings-section"><div className="container offerings-layout"><div><div className="eyebrow">WHAT THIS CAN INCLUDE</div><h2>A clear scope.<br/><em>Thoughtful execution.</em></h2><p className="muted-copy">The final deliverables depend on your goals, approved brief, media availability and production requirements.</p></div><div className="offerings-list">{s.offerings.map((x,i)=><div className="offering-row" key={x}><span>{String(i+1).padStart(2,'0')}</span><h3>{x}</h3><b>↗</b></div>)}</div></div></section>
  <section className="process-section section-pad"><div className="container"><div className="section-heading"><div><div className="eyebrow">HOW WE APPROACH IT</div><h2>From brief to<br/><em>next steps.</em></h2></div><p>A practical process keeps expectations clear, gives the work direction and helps surface dependencies early.</p></div><div className="detail-process-grid">{s.process.map((x,i)=><article className="detail-process-card" key={x.title}><span>0{i+1}</span><h3>{x.title}</h3><p>{x.text}</p></article>)}</div></div></section>
  {s.slug==='digital-marketing'&&<section className="digital-child-section section-pad"><div className="container"><div className="eyebrow">DIGITAL WORKSTREAMS</div><h2>Choose your <em>next step.</em></h2><div className="digital-child-grid">{digitalChildServices.map((x,i)=><Link href={`/services/digital-marketing/${x.slug}`} className="digital-child-card" key={x.slug}><span>0{i+1}</span><h3>{x.name}</h3><p>{x.desc}</p><b>Explore service ↗</b></Link>)}</div></div></section>}
  <section className="related-section section-pad"><div className="container"><div className="section-heading"><div><div className="eyebrow">RELATED SERVICES</div><h2>Keep the momentum <em>going.</em></h2></div><Link href="/services/digital-marketing" className="text-link">All services ↗</Link></div><div className="related-grid">{related.map(x=><Link className="related-card" href={`/services/${x.slug}`} key={x.slug}><span>{x.eyebrow}</span><h3>{x.name}</h3><p>{x.short}</p><b>Explore ↗</b></Link>)}</div></div></section>
  <section className="cta-section"><div className="container cta-box"><div className="cta-orb">K<span>•</span></div><div><div className="eyebrow eyebrow-light">LET’S TALK ABOUT {s.name.toUpperCase()}</div><h2>Have a project<br/><em>in mind?</em></h2><p>Share your goals and requirements. We’ll discuss the appropriate next step.</p></div><Link href="/contact" className="button button-white">Enquire now <span>↗</span></Link></div></section>
  </>}
